function CartSummary({ items }) {
  // WRONG: storing a value derivable from props in state
  // const [total, setTotal] = useState(0);
  // useEffect(() => setTotal(items.reduce(...)), [items]); // easy to get out of sync

  // RIGHT: derive it directly — no stale-state risk
  const total = items.reduce((sum, item) => sum + item.price * item.qty, 0);

  // For expensive derivations, memoize:
  const sortedItems = useMemo(
    () => [...items].sort((a, b) => a.name.localeCompare(b.name)),
    [items]
  );

  return (
    <div>
      <p>Total: ${total.toFixed(2)}</p>
      {sortedItems.map(i => <div key={i.id}>{i.name}</div>)}
    </div>
  );
}

import { createPortal } from 'react-dom';
import { useEffect, useRef } from 'react';

function Modal({ isOpen, onClose, children }) {
  const portalRoot = useRef(document.getElementById('modal-root'));

  // Focus management
  useEffect(() => {
    if (isOpen) {
      const firstFocusable = portalRoot.current?.querySelector(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      );
      firstFocusable?.focus();
    }
  }, [isOpen]);

  if (!isOpen) return null;

  return createPortal(
    <div
      role="dialog"
      aria-modal="true"
      className="modal-overlay"
      onClick={onClose}
    >
      <div className="modal-content" onClick={e => e.stopPropagation()}>
        {children}
        <button onClick={onClose}>Close</button>
      </div>
    </div>,
    portalRoot.current
  );
}

import React from 'react';

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error) {
    // Update state to render fallback UI on next render
    return { hasError: true, error };
  }

  componentDidCatch(error, info) {
    // Log to error tracking service
    console.error('Error Boundary caught:', error, info.componentStack);
  }

  render() {
    if (this.state.hasError) {
      return this.props.fallback ?? <p>Something went wrong.</p>;
    }
    return this.props.children;
  }
}

// Usage: wrap each independent section separately
function App() {
  return (
    <>
      <ErrorBoundary fallback={<p>Sidebar unavailable</p>}>
        <Sidebar />
      </ErrorBoundary>
      <ErrorBoundary fallback={<p>Content unavailable</p>}>
        <MainContent />
      </ErrorBoundary>
    </>
  );
}

