import { useReducer } from 'react';

const initialState = { step: 1, items: [], coupon: null, error: null };

function cartReducer(state, action) {
  switch (action.type) {
    case 'ADD_ITEM':
      return { ...state, items: [...state.items, action.payload] };
    case 'APPLY_COUPON':
      return { ...state, coupon: action.payload, error: null };
    case 'COUPON_ERROR':
      return { ...state, error: action.payload };
    case 'NEXT_STEP':
      return { ...state, step: state.step + 1 };
    case 'RESET':
      return initialState;
    default:
      return state;
  }
}

function CartForm() {
  const [state, dispatch] = useReducer(cartReducer, initialState);

  return (
    <div>
      <p>Step {state.step}</p>
      <button onClick={() => dispatch({ type: 'NEXT_STEP' })}>Continue</button>
      <button
        onClick={() =>
          dispatch({ type: 'APPLY_COUPON', payload: 'SAVE20' })
        }
      >
        Apply Coupon
      </button>
    </div>
  );
}

// On the client, we 'hydrate' the server-rendered HTML
